14	export async function createCodeAssistContentGenerator(
15	  httpOptions: HttpOptions,
16	  authType: AuthType,
17	  config: Config,
18	  sessionId?: string,
19	): Promise<ContentGenerator> {
20	  if (
21	    authType === AuthType.LOGIN_WITH_GOOGLE ||
22	    authType === AuthType.COMPUTE_ADC
23	  ) {
24	    const authClient = await getOauthClient(authType, config);
25	    const userData = await setupUser(authClient, config, httpOptions);
26	    return new CodeAssistServer(
27	      authClient,
28	      userData.projectId,
29	      httpOptions,
30	      sessionId,
31	      userData.userTier,
32	      userData.userTierName,
33	      userData.paidTier,
34	      config,
35	    );
36	  }
37	
38	  throw new Error(`Unsupported authType: ${authType}`);
39	}
40	
41	export function getCodeAssistServer(
42	  config: Config,
43	): CodeAssistServer | undefined {
44	  let server = config.getContentGenerator();
45	
46	  // Unwrap LoggingContentGenerator if present
47	  if (server instanceof LoggingContentGenerator) {
48	    server = server.getWrapped();
49	  }
50	
51	  if (!(server instanceof CodeAssistServer)) {
52	    return undefined;
53	  }
54	  return server;
55	}
