196	  private _getEndpointUrl(
197	    req: GenerateContentParameters,
198	    method: 'generateContent' | 'generateContentStream',
199	  ): ServerDetails {
200	    // Case 1: Authenticated with a Google account (`gcloud auth login`).
201	    // Requests are routed through the internal CodeAssistServer.
202	    if (this.wrapped instanceof CodeAssistServer) {
203	      const url = new URL(this.wrapped.getMethodUrl(method));
204	      const port = url.port
205	        ? parseInt(url.port, 10)
206	        : url.protocol === 'https:'
207	          ? 443
208	          : 80;
209	      return { address: url.hostname, port };
210	    }
211	
212	    const genConfig = this.config.getContentGeneratorConfig();
213	
214	    // Case 2: Using an API key for Vertex AI.
215	    if (genConfig?.vertexai) {
216	      const location = process.env['GOOGLE_CLOUD_LOCATION'];
217	      if (location) {
218	        return { address: `${location}-aiplatform.googleapis.com`, port: 443 };
219	      } else {
220	        return { address: 'unknown', port: 0 };
221	      }
222	    }
223	
224	    // Case 3: Default to the public Gemini API endpoint.
225	    // This is used when an API key is provided but not for Vertex AI.
226	    return { address: `generativelanguage.googleapis.com`, port: 443 };
227	  }
