7	import { useState, useEffect } from 'react';
8	import { persistentState } from '../../utils/persistentState.js';
9	import crypto from 'node:crypto';
10	
11	const DEFAULT_MAX_BANNER_SHOWN_COUNT = 5;
12	
13	// Track banners incremented during this session to prevent multiple increments
14	// on React unmounts/remounts
15	const sessionIncrementedBanners = new Set<string>();
16	
17	// For testing purposes
18	export function _clearSessionBannersForTest() {
19	  sessionIncrementedBanners.clear();
20	}
21	
22	interface BannerData {
23	  defaultText: string;
24	  warningText: string;
25	}
26	
27	export function useBanner(bannerData: BannerData) {
28	  const { defaultText, warningText } = bannerData;
29	
30	  const [bannerCounts] = useState(
31	    () => persistentState.get('defaultBannerShownCount') || {},
32	  );
33	
34	  const activeText = warningText ? warningText : defaultText;
35	
36	  const hashedText = crypto
37	    .createHash('sha256')
38	    .update(activeText)
39	    .digest('hex');
40	
41	  const currentBannerCount = bannerCounts[hashedText] || 0;
42	
43	  const showBanner =
44	    activeText !== '' &&
45	    (currentBannerCount < DEFAULT_MAX_BANNER_SHOWN_COUNT ||
46	      activeText.includes('Antigravity'));
47	
48	  const rawBannerText = showBanner ? activeText : '';
49	  const bannerText = rawBannerText.replace(/\\n/g, '\n');
50	
51	  useEffect(() => {
52	    if (showBanner && activeText) {
53	      if (!sessionIncrementedBanners.has(activeText)) {
54	        sessionIncrementedBanners.add(activeText);
55	
56	        const allCounts = persistentState.get('defaultBannerShownCount') || {};
57	        const current = allCounts[hashedText] || 0;
58	
59	        persistentState.set('defaultBannerShownCount', {
60	          ...allCounts,
61	          [hashedText]: current + 1,
62	        });
63	      }
64	    }
65	  }, [showBanner, activeText, hashedText]);
66	
67	  return {
68	    bannerText,
69	  };
