34	export const FRONTMATTER_REGEX =
35	  /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n([\s\S]*))?/;
36	
37	/**
38	 * Parses frontmatter content using YAML with a fallback to simple key-value parsing.
39	 * This handles cases where description contains colons that would break YAML parsing.
40	 */
41	export function parseFrontmatter(
42	  content: string,
43	): { name: string; description: string } | null {
44	  try {
45	    const parsed = load(content);
46	    if (parsed && typeof parsed === 'object') {
47	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
48	      const { name, description } = parsed as Record<string, unknown>;
49	      if (typeof name === 'string' && typeof description === 'string') {
50	        return { name, description };
51	      }
52	    }
53	  } catch (yamlError) {
54	    debugLogger.debug(
55	      'YAML frontmatter parsing failed, falling back to simple parser:',
56	      yamlError,
57	    );
58	  }
59	
60	  return parseSimpleFrontmatter(content);
61	}
62	
63	/**
64	 * Simple frontmatter parser that extracts name and description fields.
65	 * Handles cases where values contain colons that would break YAML parsing.
66	 */
67	function parseSimpleFrontmatter(
68	  content: string,
69	): { name: string; description: string } | null {
70	  const lines = content.split(/\r?\n/);
71	  let name: string | undefined;
72	  let description: string | undefined;
73	
74	  for (let i = 0; i < lines.length; i++) {
75	    const line = lines[i];
76	
77	    // Match "name:" at the start of the line (optional whitespace)
78	    const nameMatch = line.match(/^\s*name:\s*(.*)$/);
79	    if (nameMatch) {
80	      name = nameMatch[1].trim();
81	      continue;
82	    }
83	
84	    // Match "description:" at the start of the line (optional whitespace)
85	    const descMatch = line.match(/^\s*description:\s*(.*)$/);
86	    if (descMatch) {
87	      const descLines = [descMatch[1].trim()];
88	
89	      // Check for multi-line description (indented continuation lines)
90	      while (i + 1 < lines.length) {
91	        const nextLine = lines[i + 1];
92	        // If next line is indented, it's a continuation of the description
93	        if (nextLine.match(/^[ \t]+\S/)) {
94	          descLines.push(nextLine.trim());
95	          i++;
96	        } else {
97	          break;
98	        }
99	      }
100	
101	      description = descLines.filter(Boolean).join(' ');
102	      continue;
103	    }
104	  }
105	
106	  if (name !== undefined && description !== undefined) {
107	    return { name, description };
108	  }
109	  return null;
110	}
111	
112	/**
113	 * Discovers and loads all skills in the provided directory.
114	 */
115	export async function loadSkillsFromDir(
116	  dir: string,
117	): Promise<SkillDefinition[]> {
118	  const discoveredSkills: SkillDefinition[] = [];
119	
120	  try {
121	    const absoluteSearchPath = path.resolve(dir);
122	    const stats = await fs.stat(absoluteSearchPath).catch(() => null);
123	    if (!stats || !stats.isDirectory()) {
124	      return [];
125	    }
126	
127	    const pattern = ['SKILL.md', '*/SKILL.md'];
128	    const skillFiles = await glob(pattern, {
129	      cwd: absoluteSearchPath,
130	      absolute: true,
131	      nodir: true,
132	      ignore: ['**/node_modules/**', '**/.git/**'],
133	    });
134	
135	    for (const skillFile of skillFiles) {
136	      const metadata = await loadSkillFromFile(skillFile);
137	      if (metadata) {
138	        discoveredSkills.push(metadata);
139	      }
140	    }
141	
142	    if (discoveredSkills.length === 0) {
143	      const files = await fs.readdir(absoluteSearchPath);
144	      if (files.length > 0) {
145	        debugLogger.debug(
146	          `Failed to load skills from ${absoluteSearchPath}. The directory is not empty but no valid skills were discovered. Please ensure SKILL.md files are present in subdirectories and have valid frontmatter.`,
147	        );
148	      }
149	    }
150	  } catch (error) {
151	    coreEvents.emitFeedback(
152	      'warning',
153	      `Error discovering skills in ${dir}:`,
154	      error,
155	    );
156	  }
157	
158	  return discoveredSkills;
159	}
160	
161	/**
162	 * Loads a single skill from a SKILL.md file.
163	 */
164	export async function loadSkillFromFile(
165	  filePath: string,
166	): Promise<SkillDefinition | null> {
167	  try {
168	    const content = await fs.readFile(filePath, 'utf-8');
169	    const match = content.match(FRONTMATTER_REGEX);
170	    if (!match) {
171	      return null;
172	    }
173	
174	    const frontmatter = parseFrontmatter(match[1]);
175	    if (!frontmatter) {
176	      return null;
177	    }
178	
179	    // Sanitize name for use as a filename/directory name (e.g. replace ':' with '-')
180	    const sanitizedName = frontmatter.name.replace(/[:\\/<>*?"|]/g, '-');
181	
182	    return {
183	      name: sanitizedName,
184	      description: frontmatter.description,
185	      location: filePath,
186	      body: match[2]?.trim() ?? '',
187	    };
188	  } catch (error) {
189	    debugLogger.log(`Error parsing skill file ${filePath}:`, error);
190	    return null;
191	  }
192	}
