/**
 * Platform-specific installation information for the Antigravity companion CLI.
 */
export interface AntigravityInstallInfo {
  /** Human-readable name of the detected platform. */
  platformName: string;
  /** The shell command used to install the Antigravity CLI on the platform. */
  installCmd: string;
}

/**
 * Returns platform-specific installation information for the Antigravity CLI,
 * or `null` for unsupported platforms.
 *
 * On Windows, the shell is detected via the `PSModulePath` environment
 * variable: when set, PowerShell instructions are returned; otherwise the
 * Command Prompt fallback is used.
 *
 * @param platform The platform to resolve instructions for. Defaults to the
 *   current process platform.
 */
export function getAntigravityInstallInfo(
  platform: NodeJS.Platform = process.platform,
): AntigravityInstallInfo | null {
  switch (platform) {
    case 'darwin':
      return {
        platformName: 'macOS',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'linux':
      return {
        platformName: 'Linux',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'win32':
      if (process.env['PSModulePath']) {
        return {
          platformName: 'Windows (PowerShell)',
          installCmd: 'irm https://antigravity.google/cli/install.ps1 | iex',
        };
      }
      return {
        platformName: 'Windows (Command Prompt)',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.cmd -o install.cmd && install.cmd && del install.cmd',
      };
    default:
      return null;
  }
}
