import { CommandKind, type SlashCommand } from './types.js';
import { MessageType, type HistoryItemHelp } from '../types.js';
import { getAntigravityInstallInfo } from '../utils/antigravityUtils.js';

const ANTIGRAVITY_DOCS_URL =
  'https://antigravity.google/docs/cli-getting-started';

export const helpCommand: SlashCommand = {
  name: 'help',
  kind: CommandKind.BUILT_IN,
  description: 'For help on gemini-cli',
  autoExecute: true,
  action: async (context, args) => {
    const query = (args ?? '').toLowerCase();

    if (
      query.includes('antigravity') &&
      (query.includes('install') || query.includes('migrate'))
    ) {
      const installInfo = getAntigravityInstallInfo();
      if (installInfo) {
        context.ui.addItem(
          {
            type: MessageType.INFO,
            text: `To install the Antigravity CLI on ${installInfo.platformName}, run:\n\n${installInfo.installCmd}\n\nFor more information, see ${ANTIGRAVITY_DOCS_URL}`,
          },
          Date.now(),
        );
      } else {
        context.ui.addItem(
          {
            type: MessageType.INFO,
            text: `Your platform is not supported for automatic installation. See ${ANTIGRAVITY_DOCS_URL} for instructions on installing the Antigravity CLI.`,
          },
          Date.now(),
        );
      }
      return;
    }

    const helpItem: Omit<HistoryItemHelp, 'id'> = {
      type: MessageType.HELP,
      timestamp: new Date(),
    };

    context.ui.addItem(helpItem);
  },
};
